import threadingfrom typing import List, Tuple, Set, Optional, TypedDict, NotRequired, Callable, Anyfrom pynput import keyboardimport copyimport queueimport win_mouse_listenerfrom .other_key_map import OTHER_KEY_MAPclass HotkeyType(TypedDict):    name: str    value: Set[str]    down_fun: NotRequired[Optional[Callable]]    up_fun: NotRequired[Optional[Callable]]class Keyboard:    def __init__(            self,            hotkey_list: List[HotkeyType],            tk_win=None,            save_fun: Callable[[str | None, set | None], None] | None = None,            validate_keys_fun: Callable[[str, set], None] | None = None,            run_fun_callback: Callable[[Callable], Any | None] | None = None,            is_no_func_print: bool = True,            is_print_info: bool = True,            is_read_mouse: bool = False,            is_read_mouse_left: bool = False,            is_read_mouse_right: bool = True,            is_read_mouse_scroll: bool = False,            mouse_hook_func = win_mouse_listener.hook,    ):        """        全局热键管理器。        Args:            hotkey_list: list[dict] - 热键配置列表，value请注意一定是set类型。每项格式：                {'name': str, 'value': set[str], 'down_fun': callable, 'up_fun': callable}            tk_win（即将弃用）: tkinter.Tk or None - 若提供，回调通过 win.after 调度到主线程。如果你使用其他UI框架，请在下面的参数中使用非阻塞式的调用            save_fun: callable or None - 注册保存热键时模块会调用的函数 save_fun(name, value)。存储时请自行转换为List。            validate_keys_fun: callable or None - 注册采集模式下松手后先调用的函数 validate_keys_fun(name, value)，用于给用户展示即将设置的按键。                                            如果你注册了fitter_fun，请在用户点击“保存设置”后，调用一次set_one_hotkey_dict触发保存，该函数内部会自动触发save_fun。                                            如果你没注册，将在松手后立刻设置按键并调用save_fun。            run_fun_callback: 若提供，回调通过run_fun()进行调用。请传递一个用于在UI线程调用函数的函数进来。此参数的调用方法优先级高于tk_win。                    例如【lambda func: win.after(0, func)】            is_no_func_print: 是否打印无回调信息            is_print_info: 是否打印Info消息            is_read_mouse: 是否读取鼠标消息(默认False)            is_read_mouse_left: 开启鼠标后，是否读取鼠标左键(默认False)            is_read_mouse_right: 开启鼠标后，是否读取鼠标右键(默认True)            is_read_mouse_scroll: 开启鼠标后，是否读取鼠标滚轮(默认False)            mouse_hook_func: 是否使用自定义的mouse注册方法，用于多个mouse hook时，使用一个统一的管理器注册回调        """        self.validate_keys_fun=validate_keys_fun        self.save_fun=save_fun        self.is_no_func_print = is_no_func_print        self.is_print_info = is_print_info        self.is_read_mouse = is_read_mouse        self.is_read_mouse_left = is_read_mouse_left        self.is_read_mouse_right = is_read_mouse_right        self.is_read_mouse_scroll = is_read_mouse_scroll        self.mouse_hook_func = mouse_hook_func        if tk_win is not None:            self._xiaoe_keyboard_print("为了增加模块通用性，tk_win参数即将弃用，后续请使用run_fun_callback参数代替。\n"                                       "例如：tk_win = win -> run_fun_callback = lambda func: win.after(0, func)", "warning")        def _win_after(fun,*args, **kwargs):            run_fun=lambda :fun(*args, **kwargs)            if run_fun_callback is not None:                run_fun_callback(run_fun)                return            if tk_win is not None:                tk_win.after(0, run_fun)                return            run_fun()        self.running = _win_after        self.queue = queue.Queue()        self.mouse_queue = queue.Queue()        self.hm = None        self.hotkey_setting: str | None = None        self._validate_hotkey_list(hotkey_list)        self.hotkey_list: List[HotkeyType] = hotkey_list        self.start()    def start(self):        """开启监听线程"""        self.listener_process = threading.Thread(target=self._keyboard_listener, daemon=True)        self.listener_process.start()        self.key_loop_process = threading.Thread(target=self._key_loop, daemon=True)        self.key_loop_process.start()        if self.is_read_mouse:            self.mouse_loop_process = threading.Thread(target=self._mouse_loop, daemon=True)            self.mouse_loop_process.start()            self.mouse_hook_func(lambda event: self.mouse_listener(event))    def get_hotkey_names(self) -> Tuple[str, ...]:        """        获取已注册的热键名字        """        return tuple(key_info['name'] for key_info in self.hotkey_list)    def get_hotkey_setting(self) -> str | None:        """        获取当前的按键设置状态        """        return self.hotkey_setting    def set_hotkey_setting(self, name: str | None) -> None:        """        切换到设置热键状态，软件包将读取用户接下来的热键，用户松开第一个键后，        注册了fitter_fun：            1.软件包自动调用fitter_fun。            2.请在用户点击“保存按键”后，            手动调用set_one_hotkey_dict进行按键设置应用。        没注册fitter_fun：            软件包会直接调用set_one_hotkey_dict进行按键设置应用。        set_one_hotkey_dict会自行调用你注册的save_fun函数。        Args:            name: 即将要设置的按键，None表示退出设置状态。        """        if name is not None and name not in self.get_hotkey_names():            self._xiaoe_keyboard_print(                f"未注册 {name} 按键！"                f"当前注册的按键：{self.get_hotkey_names()}",                "Warning"            )            return        if name is None:            self._xiaoe_keyboard_print(                f"已退出 {self.hotkey_setting} 按键设置状态"            )        else:            self._xiaoe_keyboard_print(                f"正在设置 {name} 按键，即将读取你按下的组合键"            )        self.hotkey_setting = name    def set_one_hotkey_dict(self, name: str, value: set) -> None:        """        用于手动触发按键的应用、保存。        Args:            name: 即将要设置的按键。            value: 按键值。        """        for i in range(len(self.hotkey_list)):            if name == self.hotkey_list[i]['name']:                self.hotkey_list[i]['value'] = value                if self.save_fun is not None:                    self.running(self.save_fun,name,value)                self._xiaoe_keyboard_print(                    f"设置 {name} 按键为 {value} 成功"                )                return        if self.save_fun is not None:            self.running(self.save_fun,None,None)            self._xiaoe_keyboard_print(                f"未注册 {name} 按键！设置失败。"                f"当前注册的按键：{self.get_hotkey_names()}",                "Warning"            )    def stop(self):        """停止监听并清理资源"""        # 1. 向队列塞入 None，解除 _key_loop 线程的阻塞        self.queue.put(None)        # 2. 停止 pynput 的底层钩子        if self.hm is not None:            self.hm.stop()        if self.is_read_mouse:            # mouse.unhook_all()            self.mouse_queue.put(None)    def _keyboard_listener(self):        # 设置PyHook键盘监听        self.key_set = set()        self.hm = keyboard.Listener(on_press=self._down_keyboard, on_release=self._up_keyboard)        # 开始消息循环        self.hm.start()    def _xiaoe_keyboard_print(self, text, level = "Info"):        if not self.is_print_info and level == "Info":            return        print(f"[Xiaoe Keyboard] [{level}]: {text}")    def _validate_hotkey_list(self, hotkey_list):        """        检查 hotkey_list 格式是否符合要求。        Args:            hotkey_list: 按键列表        Raises:            TypeError: 参数不是列表，或列表元素不是字典，或类型错误            KeyError: 缺少必填字段 'name' 或 'value'            ValueError: 字段值类型不正确        """        if not isinstance(hotkey_list, list):            raise TypeError("hotkey_list 必须是列表类型")        for idx, item in enumerate(hotkey_list):            if not isinstance(item, dict):                raise TypeError(f"第 {idx} 项不是字典类型")            # 检查必填字段            if 'name' not in item:                raise KeyError(f"第 {idx} 项缺少 'name' 字段")            if 'value' not in item:                raise KeyError(f"{item['name']} 项缺少 'value' 字段")            if not isinstance(item['value'], set):                raise TypeError(f"{item['name']} 项的 'value' 必须是集合(set)类型")            # 检查可选回调            has_down = 'down_fun' in item            has_up = 'up_fun' in item            if not has_down and not has_up:                self._xiaoe_keyboard_print(                    f"{item['name']} 项 既没有 down_fun 也没有 up_fun",                    "Warning"                )            # 如果存在回调但不是可调用对象，打印警告            if has_down and not callable(item['down_fun']):                raise TypeError(                    f"{item['name']} 项的 down_fun 不可调用",                )            if has_up and not callable(item['up_fun']):                self._xiaoe_keyboard_print(                    f"{item['name']} 项的 up_fun 不可调用",                    "Warning"                )    @staticmethod    def _get_key_value(event):        try:            key=event.name        except:            try:                key=chr(event.vk)            except:                # show_suc()                return None        key = OTHER_KEY_MAP.get(key, key)        return key    def _down_keyboard(self, event):        #print(vars(event))        key = self._get_key_value(event)        if key is None:            return        if (key in self.key_set) or (key=="cmd"):#防止系统自动重复点击            return        self.key_set.add(key)        self.queue.put({'down': True, 'value': copy.copy(self.key_set),'now_key':key})    def _up_keyboard(self, event):        key = self._get_key_value(event)        if key is None:            return        self.queue.put({'down': False, 'value': copy.copy(self.key_set),'now_key':key})        self.key_set.discard(key)    def _no_func(self, key_name, func_name):        if not self.is_no_func_print:            return        self._xiaoe_keyboard_print(f'按键 {key_name} 没有设置 {func_name}')    def _key_loop(self):        """循环获取队列"""        def run_fun(m,fun_name: str):            funs=[]            value = m['value']            now_key = m['now_key']            l=0            for i in self.hotkey_list:                now_list_value = i['value']                if None in now_list_value:                    continue                if not now_list_value <= value:                    continue                if now_key not in now_list_value:                    continue                new_l=len(now_list_value)                if not new_l>=l:                    continue                if new_l>l:                    l=new_l                    funs=[]                funs.append(                    i.get(                        fun_name,                        lambda :self._no_func(i.get("name", "unknown name key"), fun_name)                    )                )            # if fun is not None:            for fun in funs:                self.running(fun)        while True:            m = self.queue.get(block=True)            if m is None:                break            # print(m['now_key'])            if m['down']:                run_fun(m,'down_fun')                #self.restart.next()            else:                if not self.hotkey_setting is None:                    if self.validate_keys_fun is not None:                        self.running(self.validate_keys_fun, self.hotkey_setting, m['value'])                    else:                        self.set_one_hotkey_dict(self.hotkey_setting,m['value'])                    self.set_hotkey_setting(None)                else:                    run_fun(m,'up_fun')                    #self.restart.next()    def _mouse_loop(self):        while True:            event = self.mouse_queue.get(block=True)            if event is None:                break            if isinstance(event, win_mouse_listener.ButtonEvent):                button = f'mouse_{event.button}'                if not self.is_read_mouse_left and button == 'mouse_left':                    continue                if not self.is_read_mouse_right and button == 'mouse_right':                    continue                event_type = event.event_type                is_down = event_type != 'up'                if is_down:                    self.key_set.add(button)                self.queue.put({'down': is_down, 'value': copy.copy(self.key_set), 'now_key': button})                if not is_down:                    self.key_set.discard(button)                continue            if isinstance(event, win_mouse_listener.WheelEvent) and self.is_read_mouse_scroll:                button = f"mouse_scroll_{'up' if event.delta > 0 else 'down'}"                self.key_set.add(button)                self.queue.put({'down': True, 'value': copy.copy(self.key_set), 'now_key': button})                self.queue.put({'down': False, 'value': copy.copy(self.key_set), 'now_key': button})                self.key_set.discard(button)                continue    def mouse_listener(self, event):        if isinstance(event, (win_mouse_listener.ButtonEvent, win_mouse_listener.WheelEvent)):            self.mouse_queue.put(event)